//! Parity and regression tests for the kitten_tts family.
//!
//! Pinned fixtures reside in `testdata/tts_kitten_tts/`, generated by
//! `tools/gen_kitten_tts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The generator
//! runs the true reference modules (preprocess.py, the espeak phonemizer,
//! kitten_tts.py text helpers, and the instrumented `Model.__call__` /
//! `Model.generate` paths) against a tiny seeded model, so the traces
//! carry the reference string pipeline, per-stage tensors, and end-to-end
//! audio.

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use serde_json::Value;

use super::frontend::{
    basic_english_tokenize, chunk_text, ensure_punctuation, TextCleaner, TextPreprocessor,
};
use super::{
    crossfade, fake_quant_dynamic_u8, maybe_fake_quant, symbol_table, Model, ModelConfig, Rng,
};

/// The fixture generator pins `mx.random.seed(1234)` around every
/// stochastic call; the model under test must use the same key sequence.
const FIXTURE_SEED: u64 = 1234;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_kitten_tts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn u32_vec(value: &Value) -> Vec<u32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as u32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

fn assert_close(got: &[f32], want: &[f32], tolerance: f32, stage: &str) {
    let diff = max_abs_diff(got, want);
    assert!(
        diff <= tolerance,
        "{stage}: diff {diff} exceeds {tolerance} (got {} values)",
        got.len()
    );
}

/// Measured maximum differences against the fixture traces when the
/// gates were frozen; assertions use these values, not re-measured ones.
/// String stages are exact, model stages are f32 conv/FFT reordering.
const FEATURE_TOLERANCE: f32 = 2e-4;
/// Generator waveform from the pinned spectrum: measured 1.3e-4 at the
/// largest audio magnitude (gate 10x above).
const AUDIO_TOLERANCE: f32 = 1e-3;
/// End-to-end waveform smoke: the reference's phase channel is
/// FFT-implementation dependent at the arctan2 branch cut (the Nyquist
/// bin's imaginary zero sign and the near-zero interior bins), so the raw
/// text-to-waveform path cannot match bit-tightly; the measured
/// correlations are 0.55-0.63 and the tight waveform gate runs from the
/// pinned spectrum.
const E2E_CORRELATION_FLOOR: f64 = 0.45;

#[test]
fn preprocessor_matches_the_reference_cases() {
    let traces = read_json(&testdata("frontend/traces.json"));
    let preprocessor = TextPreprocessor::new();
    for case in traces["preprocess_cases"].as_array().expect("cases") {
        let got = preprocessor
            .process(case["input"].as_str().expect("input"))
            .expect("preprocess");
        assert_eq!(
            got,
            case["output"].as_str().expect("output"),
            "case {}",
            case["name"]
        );
    }
}

#[test]
fn chunk_and_tokenize_match_the_reference() {
    let traces = read_json(&testdata("frontend/traces.json"));
    for case in traces["chunk_cases"].as_array().expect("cases") {
        let text = case["input"].as_str().expect("input");
        assert_eq!(
            ensure_punctuation(text),
            case["punctuated"].as_str().expect("punctuated"),
            "case {}",
            case["name"]
        );
        let got = chunk_text(text, 400);
        let want: Vec<String> = case["chunks"]
            .as_array()
            .expect("chunks")
            .iter()
            .map(|v| v.as_str().expect("chunk").to_string())
            .collect();
        assert_eq!(got, want, "case {}", case["name"]);
    }
    for case in traces["tokenize_cases"].as_array().expect("cases") {
        let got = basic_english_tokenize(case["input"].as_str().expect("input"));
        let want: Vec<String> = case["tokens"]
            .as_array()
            .expect("tokens")
            .iter()
            .map(|v| v.as_str().expect("token").to_string())
            .collect();
        assert_eq!(got, want);
    }
}

#[test]
fn cleaner_contract_matches_the_reference() {
    let traces = read_json(&testdata("frontend/traces.json"));
    let cleaner = TextCleaner::new();
    for case in traces["cleaner_cases"].as_array().expect("cases") {
        let phonemes = case["phonemes"].as_str().expect("phonemes");
        let token_string = basic_english_tokenize(phonemes).join(" ");
        assert_eq!(
            token_string,
            case["token_string"].as_str().expect("token_string")
        );
        let ids: Vec<u32> = cleaner.clean(&token_string);
        assert_eq!(ids, u32_vec(&case["ids"]));
    }
}

#[test]
fn symbol_table_matches_the_pinned_symbols() {
    let traces = read_json(&testdata("frontend/traces.json"));
    let pinned: Vec<String> = traces["symbols"]
        .as_array()
        .expect("symbols")
        .iter()
        .map(|v| v.as_str().expect("symbol").to_string())
        .collect();
    let table = symbol_table();
    let cleaner = TextCleaner::new();
    assert_eq!(cleaner.symbols(), pinned, "symbol list order");
    assert_eq!(table.len(), pinned.len(), "table size");
    for symbol in &pinned {
        assert!(table.contains_key(symbol), "missing symbol {symbol}");
    }
}

fn stage_model() -> Model {
    let mut model = Model::open(&testdata("stages")).expect("family model loads");
    model.seed = FIXTURE_SEED;
    model
}

/// Mirrors the reference `Model.__call__` stage by stage (the fixture's
/// instrumented path), returning the pinned intermediates. The generator
/// runs from the PINNED harmonic spectrum: the reference's phase channel
/// is discontinuous at the arctan2 branch cut wherever the true imaginary
/// part sits below FFT rounding error, so the spectrum is pinned as an
/// input and the waveform gate runs from there.
struct Stages {
    bert_out: Vec<f32>,
    d_en: Vec<f32>,
    duration_logits: Vec<f32>,
    durations_raw: Vec<f32>,
    pred_dur: Vec<i32>,
    en: Vec<f32>,
    f0: Vec<f32>,
    n: Vec<f32>,
    t_en: Vec<f32>,
    asr: Vec<f32>,
    f0_conv: Vec<f32>,
    n_conv: Vec<f32>,
    encode: Vec<f32>,
    asr_res: Vec<f32>,
    blocks: Vec<Vec<f32>>,
    gen_x: Vec<f32>,
    f0_up: Vec<f32>,
    har_source: Vec<f32>,
    stft_mag: Vec<f32>,
    stft_phase: Vec<f32>,
}

fn run_stages(model: &Model, ids: &[u32], ref_s: &[f32], speed: f32) -> Stages {
    use super::{maybe_fake_quant, ops, round_ties_even, Rng};

    let seq = ids.len();
    let bert_out = model.albert.forward(ids).expect("albert");
    let bert_out = maybe_fake_quant(&bert_out, model.quant.enabled("bert_encoder"));
    let d_en = ops::linear(
        &bert_out,
        &model.bert_encoder_w,
        Some(&model.bert_encoder_b),
        seq,
        model.albert.hidden,
        model.config.hidden_dim,
    );
    let mut d_en_c = vec![0.0f32; d_en.len()];
    for t in 0..seq {
        for c in 0..model.config.hidden_dim {
            d_en_c[c * seq + t] = d_en[t * model.config.hidden_dim + c];
        }
    }
    let s = &ref_s[super::STYLE_SPLIT..];
    let s_dec = &ref_s[..super::STYLE_SPLIT];
    let d = model.predictor.text_encoder.forward(
        &d_en_c,
        seq,
        s,
        &model.quant,
        "predictor.text_encoder",
    );
    let lstm_out = model
        .predictor
        .lstm
        .forward(&d, &model.quant, "predictor.lstm");
    let classes = model.predictor.duration_proj_w.len() / model.predictor.d_hid;
    let lstm_q = maybe_fake_quant(&lstm_out, model.quant.enabled("predictor.duration_proj"));
    let duration_logits = ops::linear(
        &lstm_q,
        &model.predictor.duration_proj_w,
        Some(&model.predictor.duration_proj_b),
        seq,
        model.predictor.d_hid,
        classes,
    );
    let mut durations_raw = vec![0.0f32; seq];
    for t in 0..seq {
        let row = &duration_logits[t * classes..(t + 1) * classes];
        durations_raw[t] = row.iter().map(|v| ops::sigmoid(*v)).sum::<f32>() / speed;
    }
    let pred_dur: Vec<i32> = durations_raw
        .iter()
        .map(|v| round_ties_even(*v).max(1.0) as i32)
        .collect();
    let frames: usize = pred_dur.iter().map(|&d| d as usize).sum();
    let mut indices = Vec::with_capacity(frames);
    for (i, &n) in pred_dur.iter().enumerate() {
        for _ in 0..n {
            indices.push(i);
        }
    }
    let d_channels = model.config.hidden_dim + model.config.style_dim;
    let mut en = vec![0.0f32; d_channels * frames];
    for (frame, &ph) in indices.iter().enumerate() {
        let row = &d[ph * d_channels..(ph + 1) * d_channels];
        for (c, &v) in row.iter().enumerate() {
            en[c * frames + frame] = v;
        }
    }
    let (f0, n) = model.predictor.f0_n_train(&en, frames, s, &model.quant);
    let t_en = model
        .text_encoder
        .forward(ids, &model.quant)
        .expect("text encoder");
    let mut asr = vec![0.0f32; model.config.hidden_dim * frames];
    for (frame, &ph) in indices.iter().enumerate() {
        for c in 0..model.config.hidden_dim {
            asr[c * frames + frame] = t_en[c * seq + ph];
        }
    }

    // Decoder internals.
    let dec = &model.decoder;
    let f0_c = dec.f0_conv.forward(&f0, &model.quant, "decoder.F0_conv");
    let n_c = dec.n_conv.forward(&n, &model.quant, "decoder.N_conv");
    let cond_seq = f0_c.len();
    let mut x = vec![0.0f32; asr.len() + 2 * cond_seq];
    x[..asr.len()].copy_from_slice(&asr);
    x[asr.len()..asr.len() + cond_seq].copy_from_slice(&f0_c);
    x[asr.len() + cond_seq..].copy_from_slice(&n_c);
    let encode = dec
        .encode
        .forward(&x, cond_seq, s_dec, &model.quant, "decoder.encode");
    let asr_res = dec.asr_res.forward(&asr, &model.quant, "decoder.asr_res.0");
    let mut blocks = Vec::new();
    let mut res = true;
    let mut cur = encode.clone();
    let mut cur_seq = cond_seq;
    for (index, block) in dec.decode.iter().enumerate() {
        if res {
            let mut joined = vec![0.0f32; cur.len() + asr_res.len() + 2 * cond_seq];
            joined[..cur.len()].copy_from_slice(&cur);
            joined[cur.len()..cur.len() + asr_res.len()].copy_from_slice(&asr_res);
            joined[cur.len() + asr_res.len()..cur.len() + asr_res.len() + cond_seq]
                .copy_from_slice(&f0_c);
            joined[cur.len() + asr_res.len() + cond_seq..].copy_from_slice(&n_c);
            cur = joined;
        }
        cur = block.forward(
            &cur,
            cur_seq,
            s_dec,
            &model.quant,
            &format!("decoder.decode.{index}"),
        );
        blocks.push(cur.clone());
        if block.pool.is_some() {
            res = false;
            cur_seq *= 2;
        }
    }

    // Generator internals from the pinned harmonic spectrum.
    let gen = &dec.generator;
    let mut f0_up = vec![0.0f32; f0.len() * gen.total_upsample];
    for (t, &v) in f0.iter().enumerate() {
        for u in 0..gen.total_upsample {
            f0_up[t * gen.total_upsample + u] = v;
        }
    }
    let mut rng = Rng::new(FIXTURE_SEED);
    let har_source = gen.m_source.forward(&f0_up, &mut rng, &model.quant);
    // The pinned spectrum is supplied by the caller through the trace;
    // here it is reconstructed from the model path for the shape.
    let har = gen.har_spectrum(&har_source);
    let frames_t = 1 + har_source.len() / gen.hop;
    let _audio = gen.forward_with_har(&cur, cur_seq, s_dec, &har, &model.quant);

    Stages {
        bert_out,
        d_en: d_en_c,
        duration_logits,
        durations_raw,
        pred_dur,
        en,
        f0,
        n,
        t_en,
        asr,
        f0_conv: f0_c,
        n_conv: n_c,
        encode,
        asr_res,
        blocks,
        gen_x: cur,
        f0_up,
        har_source,
        stft_mag: har[..gen.bins * frames_t].to_vec(),
        stft_phase: har[gen.bins * frames_t..].to_vec(),
    }
}

#[test]
fn stage_pipeline_matches_the_reference_traces() {
    let traces = read_json(&testdata("stages/traces.json"));
    let model = stage_model();
    for case in traces["cases"].as_array().expect("cases") {
        let name = case["case"].as_str().expect("case").to_string();
        let ids = u32_vec(&case["input_ids"]);
        let ref_s = f32_vec(&case["ref_s"]);
        let speed = case["speed"].as_f64().expect("speed") as f32;
        let got = run_stages(&model, &ids, &ref_s, speed);
        let want_stages = Stages::from_trace(case);
        assert_eq!(got.pred_dur, want_stages.pred_dur, "{name} durations");
        for (stage, tolerance) in [
            ("bert_out", FEATURE_TOLERANCE),
            ("d_en", FEATURE_TOLERANCE),
            ("duration_logits", FEATURE_TOLERANCE),
            ("durations_raw", FEATURE_TOLERANCE),
            ("en", FEATURE_TOLERANCE),
            ("f0", FEATURE_TOLERANCE),
            ("n", FEATURE_TOLERANCE),
            ("t_en", FEATURE_TOLERANCE),
            ("asr", FEATURE_TOLERANCE),
        ] {
            let got_values = got.field(stage);
            assert_close(
                got_values,
                want_stages.field(stage),
                tolerance,
                &format!("{name} {stage}"),
            );
        }
        // The harmonic spectrum: magnitude directly, phase through its
        // unit phasor (the atan2 branch cut wraps by 2*pi).
        assert_close(
            &got.har_source,
            &want_stages.har_source,
            FEATURE_TOLERANCE,
            &format!("{name} har_source"),
        );
        assert_close(
            &got.f0_up,
            &want_stages.f0_up,
            FEATURE_TOLERANCE,
            &format!("{name} f0_up"),
        );
        assert_close(
            &got.stft_mag,
            &want_stages.stft_mag,
            FEATURE_TOLERANCE,
            &format!("{name} stft_mag"),
        );
        assert_close(
            &got.stft_phase.iter().map(|v| v.cos()).collect::<Vec<_>>(),
            &want_stages
                .stft_phase
                .iter()
                .map(|v| v.cos())
                .collect::<Vec<_>>(),
            FEATURE_TOLERANCE,
            &format!("{name} stft_phase cos"),
        );
        assert_close(
            &got.stft_phase.iter().map(|v| v.sin()).collect::<Vec<_>>(),
            &want_stages
                .stft_phase
                .iter()
                .map(|v| v.sin())
                .collect::<Vec<_>>(),
            FEATURE_TOLERANCE,
            &format!("{name} stft_phase sin"),
        );
        // Decoder blocks.
        assert_close(
            &got.f0_conv,
            &want_stages.f0_conv,
            FEATURE_TOLERANCE,
            &format!("{name} f0_conv"),
        );
        assert_close(
            &got.n_conv,
            &want_stages.n_conv,
            FEATURE_TOLERANCE,
            &format!("{name} n_conv"),
        );
        assert_close(
            &got.encode,
            &want_stages.encode,
            FEATURE_TOLERANCE,
            &format!("{name} encode"),
        );
        assert_close(
            &got.asr_res,
            &want_stages.asr_res,
            FEATURE_TOLERANCE,
            &format!("{name} asr_res"),
        );
        for (i, block) in got.blocks.iter().enumerate() {
            assert_close(
                block,
                &want_stages.blocks[i],
                FEATURE_TOLERANCE,
                &format!("{name} block{i}"),
            );
        }
        assert_close(
            &got.gen_x,
            &want_stages.gen_x,
            FEATURE_TOLERANCE,
            &format!("{name} gen_x"),
        );
    }
}

impl Stages {
    fn from_trace(case: &Value) -> Stages {
        let dec = &case["decoder"];
        Stages {
            bert_out: f32_vec(&case["bert_out"]),
            d_en: f32_vec(&case["d_en"]),
            duration_logits: f32_vec(&case["duration_logits"]),
            durations_raw: f32_vec(&case["durations_raw"]),
            pred_dur: i32_vec(&case["pred_dur"]),
            en: f32_vec(&case["en"]),
            f0: f32_vec(&case["f0"]),
            n: f32_vec(&case["n"]),
            t_en: f32_vec(&case["t_en"]),
            asr: f32_vec(&case["asr"]),
            f0_conv: f32_vec(&dec["f0_conv"]),
            n_conv: f32_vec(&dec["n_conv"]),
            encode: f32_vec(&dec["encode"]),
            asr_res: f32_vec(&dec["asr_res"]),
            blocks: dec["blocks"]
                .as_array()
                .expect("blocks")
                .iter()
                .map(f32_vec)
                .collect(),
            gen_x: f32_vec(&dec["gen_x"]),
            f0_up: f32_vec(&dec["f0_up"]),
            har_source: f32_vec(&dec["har_source"]),
            stft_mag: f32_vec(&dec["stft_mag"]),
            stft_phase: f32_vec(&dec["stft_phase"]),
        }
    }

    fn field(&self, name: &str) -> &Vec<f32> {
        match name {
            "bert_out" => &self.bert_out,
            "d_en" => &self.d_en,
            "duration_logits" => &self.duration_logits,
            "durations_raw" => &self.durations_raw,
            "en" => &self.en,
            "f0" => &self.f0,
            "n" => &self.n,
            "t_en" => &self.t_en,
            "asr" => &self.asr,
            _ => panic!("unknown stage {name}"),
        }
    }
}

/// The generator verified from the PINNED harmonic spectrum: every stage
/// from the noise convs through the waveform is a deterministic function
/// of the spectrum, so this gate is tight.
#[test]
fn generator_matches_the_reference_from_the_pinned_spectrum() {
    let traces = read_json(&testdata("stages/traces.json"));
    let model = stage_model();
    for case in traces["cases"].as_array().expect("cases") {
        let name = case["case"].as_str().expect("case").to_string();
        let dec = &case["decoder"];
        let model_stages = &dec["gen_stages"];
        let gen = &model.decoder.generator;
        // Assemble the pinned spectrum and decoder features.
        let mag = f32_vec(&dec["stft_mag"]);
        let phase = f32_vec(&dec["stft_phase"]);
        let bins = gen.bins;
        let frames_t = mag.len() / bins;
        let mut har = vec![0.0f32; 2 * bins * frames_t];
        har[..bins * frames_t].copy_from_slice(&mag);
        har[bins * frames_t..].copy_from_slice(&phase);
        let gen_x = f32_vec(&dec["gen_x"]);
        let gen_x_ch = gen.ups[0].in_ch;
        let gen_x_seq = gen_x.len() / gen_x_ch;
        let s_dec = &f32_vec(&case["ref_s"])[..super::STYLE_SPLIT];
        let audio = gen.forward_with_har(&gen_x, gen_x_seq, s_dec, &har, &model.quant);
        // Stage-by-stage comparison against the pinned generator path.
        let mut cur = gen_x.clone();
        let mut cur_seq = gen_x_seq;
        for (i, stage) in model_stages
            .as_array()
            .expect("gen stages")
            .iter()
            .enumerate()
        {
            for v in cur.iter_mut() {
                *v = leaky_relu_in_test(*v);
            }
            let x_source = gen.noise_convs[i].forward(
                &har,
                &model.quant,
                &format!("decoder.generator.noise_convs.{i}"),
            );
            // The reference noise conv runs channels-last: transpose the
            // pinned [t * out_ch + o] rows into the channel-major layout.
            let want_xs = f32_vec(&stage["noise_conv"]);
            let out_ch = gen.noise_convs[i].out_ch;
            let out_len = x_source.len() / out_ch;
            let mut want_xs_cm = vec![0.0f32; want_xs.len()];
            for t in 0..out_len {
                for o in 0..out_ch {
                    want_xs_cm[o * out_len + t] = want_xs[t * out_ch + o];
                }
            }
            assert_close(
                &x_source,
                &want_xs_cm,
                FEATURE_TOLERANCE,
                &format!("{name} noise_conv{i}"),
            );
            let xs_seq = x_source.len() / gen.noise_convs[i].out_ch;
            let x_source = gen.noise_res[i].forward(
                &x_source,
                xs_seq,
                s_dec,
                &model.quant,
                &format!("decoder.generator.noise_res.{i}"),
            );
            assert_close(
                &x_source,
                &f32_vec(&stage["noise_res"]),
                FEATURE_TOLERANCE,
                &format!("{name} noise_res{i}"),
            );
            cur = gen.ups[i].forward(&cur);
            cur_seq =
                (cur_seq - 1) * gen.ups[i].stride + gen.ups[i].kernel - 2 * gen.ups[i].padding;
            assert_close(
                &cur,
                &f32_vec(&stage["up"]),
                FEATURE_TOLERANCE,
                &format!("{name} up{i}"),
            );
            if i == gen.ups.len() - 1 {
                cur = super::constant_pad_left(&cur, gen.ups[i].out_ch, 1);
                cur_seq += 1;
            }
            for (a, b) in cur.iter_mut().zip(&x_source) {
                *a += b;
            }
            assert_close(
                &cur,
                &f32_vec(&stage["added"]),
                FEATURE_TOLERANCE,
                &format!("{name} added{i}"),
            );
            let mut acc = vec![0.0f32; cur.len()];
            let kernels = gen.resblock_kernels();
            for j in 0..kernels {
                let out = gen.resblocks[i * kernels + j].forward(
                    &cur,
                    cur_seq,
                    s_dec,
                    &model.quant,
                    &format!("decoder.generator.resblocks.{}", i * kernels + j),
                );
                for (a, b) in acc.iter_mut().zip(&out) {
                    *a += b;
                }
            }
            for a in acc.iter_mut() {
                *a /= kernels as f32;
            }
            cur = acc;
            assert_close(
                &cur,
                &f32_vec(&stage["resblocks"]),
                FEATURE_TOLERANCE,
                &format!("{name} resblocks{i}"),
            );
        }
        assert_close(
            &audio,
            &f32_vec(&case["audio"]),
            AUDIO_TOLERANCE,
            &format!("{name} generator audio"),
        );
    }
}

fn leaky_relu_in_test(v: f32) -> f32 {
    if v > 0.0 {
        v
    } else {
        v * 0.1
    }
}

#[test]
fn config_parses_fields_and_defaults() {
    let config: Value = serde_json::from_str(
        &std::fs::read_to_string(testdata("stages/config.json")).expect("config"),
    )
    .expect("config json");
    let parsed = ModelConfig::from_json(&config).expect("config parses");
    assert_eq!(parsed.hidden_dim, 32);
    assert_eq!(parsed.max_conv_dim, 32);
    assert_eq!(parsed.max_dur, 8);
    assert_eq!(parsed.n_layer, 2);
    assert_eq!(parsed.n_token, 178);
    assert_eq!(parsed.style_dim, 128);
    assert_eq!(parsed.text_encoder_kernel_size, 5);
    assert_eq!(parsed.asr_res_dim, 4);
    assert_eq!(
        parsed.decoder_out_dim, 32,
        "decoder_out_dim None -> max_conv_dim"
    );
    assert_eq!(parsed.sample_rate, 24000);
    assert_eq!(parsed.plbert.hidden_size, 24);
    assert_eq!(parsed.plbert.embedding_size, 8);
    assert_eq!(parsed.istftnet.upsample_rates, vec![4, 4]);
    assert_eq!(parsed.istftnet.gen_istft_n_fft, 32);
    assert_eq!(parsed.istftnet.gen_istft_hop_size, 4);
    let minimal = ModelConfig::from_json(&serde_json::json!({
        "hidden_dim": 16, "max_conv_dim": 16, "max_dur": 4, "n_layer": 1,
        "n_token": 32, "style_dim": 128, "text_encoder_kernel_size": 5,
        "asr_res_dim": 2,
        "plbert": minimal_plbert(),
        "istftnet": {
            "resblock_kernel_sizes": [3], "upsample_rates": [4],
            "upsample_initial_channel": 8, "resblock_dilation_sizes": [[1,3,5]],
            "upsample_kernel_sizes": [8], "gen_istft_n_fft": 16, "gen_istft_hop_size": 4
        }
    }))
    .expect("minimal config");
    assert_eq!(minimal.decoder_out_dim, 16);
    assert_eq!(minimal.sample_rate, 24000);
    assert!(minimal.speed_priors.is_empty());
    assert!(minimal.voice_aliases.is_empty());
    assert_eq!(minimal.voices_path, "voices.npz");
    assert_eq!(minimal.plbert.embedding_size, 128);
    assert_eq!(minimal.plbert.layer_norm_eps, 1e-12);
    assert!(minimal.activation_quant_modules.is_empty());
}

/// A complete `plbert` block (every field is required by from_json).
fn minimal_plbert() -> Value {
    serde_json::json!({
        "num_hidden_layers": 1, "num_attention_heads": 1, "hidden_size": 16,
        "intermediate_size": 32, "max_position_embeddings": 64, "embedding_size": 128,
        "inner_group_num": 1, "num_hidden_groups": 1, "type_vocab_size": 2,
        "layer_norm_eps": 1e-12
    })
}

fn minimal_config() -> Value {
    serde_json::json!({
        "hidden_dim": 16, "max_conv_dim": 16, "max_dur": 4, "n_layer": 1,
        "n_token": 32, "style_dim": 128, "text_encoder_kernel_size": 5,
        "asr_res_dim": 2,
        "plbert": minimal_plbert(),
        "istftnet": {
            "resblock_kernel_sizes": [3], "upsample_rates": [4],
            "upsample_initial_channel": 8, "resblock_dilation_sizes": [[1,3,5]],
            "upsample_kernel_sizes": [8], "gen_istft_n_fft": 16, "gen_istft_hop_size": 4
        }
    })
}

fn is_bad_config(error: &crate::SpeechError, field: &str) -> bool {
    matches!(error, crate::SpeechError::BadConfig { field: f, .. } if f == field)
}

#[test]
fn config_refuses_missing_and_malformed_fields() {
    let parse = |edit: &dyn Fn(&mut Value)| {
        let mut config = minimal_config();
        edit(&mut config);
        ModelConfig::from_json(&config)
    };
    assert!(parse(&|_| {}).is_ok(), "the unedited minimal config parses");
    // A missing plbert section or field must not fall back to the
    // 12-layer BERT defaults.
    let error = parse(&|c| {
        c.as_object_mut().expect("object").remove("plbert");
    })
    .unwrap_err();
    assert!(is_bad_config(&error, "plbert"), "{error}");
    let error = parse(&|c| {
        c["plbert"]
            .as_object_mut()
            .expect("object")
            .remove("hidden_size");
    })
    .unwrap_err();
    assert!(is_bad_config(&error, "plbert.hidden_size"), "{error}");
    // A zero hop divides in the harmonic-spectrum framing.
    let error = parse(&|c| c["istftnet"]["gen_istft_hop_size"] = serde_json::json!(0)).unwrap_err();
    assert!(is_bad_config(&error, "gen_istft_hop_size"), "{error}");
    let error = parse(&|c| c["istftnet"]["gen_istft_n_fft"] = serde_json::json!(1)).unwrap_err();
    assert!(is_bad_config(&error, "gen_istft_n_fft"), "{error}");
    // The generator indexes kernels, rates, and dilations by position.
    let error =
        parse(&|c| c["istftnet"]["upsample_kernel_sizes"] = serde_json::json!([3])).unwrap_err();
    assert!(is_bad_config(&error, "upsample_kernel_sizes"), "{error}");
    let error = parse(&|c| c["istftnet"]["upsample_rates"] = serde_json::json!([])).unwrap_err();
    assert!(is_bad_config(&error, "upsample_rates"), "{error}");
    let error = parse(&|c| c["istftnet"]["resblock_dilation_sizes"] = serde_json::json!([[1, 3]]))
        .unwrap_err();
    assert!(is_bad_config(&error, "resblock_dilation_sizes"), "{error}");
    let error =
        parse(&|c| c["istftnet"]["resblock_kernel_sizes"] = serde_json::json!([])).unwrap_err();
    assert!(is_bad_config(&error, "resblock_kernel_sizes"), "{error}");
}

#[test]
fn number_words_cover_the_full_i64_range() {
    use super::frontend::number_to_words;
    // These used to be dropped (empty output) at 10^15 and above.
    assert_eq!(number_to_words(1_000_000_000_000_000), "one quadrillion");
    assert_eq!(
        number_to_words(1_000_000_000_000_000_000),
        "one quintillion"
    );
    assert_eq!(
        number_to_words(i64::MAX),
        "nine quintillion two hundred twenty-three quadrillion three hundred seventy-two \
         trillion thirty-six billion eight hundred fifty-four million seven hundred \
         seventy-five thousand eight hundred seven"
    );
}

#[test]
fn oversized_integers_are_refused_not_read_as_zero() {
    let preprocessor = TextPreprocessor::new();
    // The number helpers parse with unwrap_or(0); a 25-digit literal used
    // to come out as "zero".
    let error = preprocessor
        .process("the count is 1234567890123456789012345 today")
        .unwrap_err();
    assert!(error.to_string().contains("25 digits"), "{error}");
    let error = preprocessor
        .process("total 1,234,567,890,123,456,789,012,345")
        .unwrap_err();
    assert!(error.to_string().contains("25 digits"), "{error}");
    // Up to the replace_numbers bound (9e15) is spelled out in full.
    let in_range = preprocessor
        .process("the count is 8999999999999999 today")
        .expect("below the bound");
    assert!(in_range.contains("quadrillion"), "{in_range}");
    let error = preprocessor
        .process("the count is 9000000000000000 today")
        .unwrap_err();
    assert!(error.to_string().contains("16 digits"), "{error}");
    // Decimal fraction digits are read one at a time and never parsed.
    assert!(preprocessor
        .process("pi is 3.14159265358979323846264338")
        .is_ok());
}

#[test]
fn install_voice_refuses_mismatched_tables() {
    let mut model = stage_model();
    // Half-width rows would be sliced past the end of the table.
    let error = model
        .install_voice("narrow", vec![0.25f32; 4 * 128], 4)
        .unwrap_err();
    assert!(error.to_string().contains("4 x 256"), "{error}");
    assert!(model
        .install_voice("short", vec![0.25f32; 4 * 256 - 1], 4)
        .is_err());
    assert!(model.install_voice("empty", Vec::new(), 0).is_err());
    assert!(model
        .install_voice("huge", vec![0.25f32; 4], usize::MAX)
        .is_err());
    model
        .install_voice("exact", vec![0.25f32; 4 * 256], 4)
        .expect("exact table installs");
}

#[test]
fn generation_refuses_bad_speed_and_short_style_on_every_entry_point() {
    let model = stage_model();
    let ids = [0u32, 5, 9, 0];
    let ref_s = vec![0.0f32; 256];
    // generate_segment checks these too; the durations entry point used
    // to skip the check and reach the predictor with a bad speed.
    for speed in [0.0f32, -1.0, f32::NAN, f32::INFINITY] {
        assert!(
            model
                .generate_segment_with_durations(&ids, &ref_s, speed)
                .is_err(),
            "speed {speed} must be refused"
        );
    }
    let error = model
        .generate_segment_with_durations(&ids, &ref_s[..128], 1.0)
        .unwrap_err();
    assert!(error.to_string().contains("ref_s must be"), "{error}");
    // The chunked path reaches the same guard through its resolved speed.
    let phonemize = |_: &str| "həlˈoʊ".to_string();
    assert!(model
        .synthesize_with(
            "hello there",
            &phonemize,
            "test-voice",
            0.0,
            400,
            20,
            200,
            200
        )
        .is_err());
}

